dos os prazos, no [NOME], serão contados em dia útil (Lei 13.728/2018).  P.I.C. ", "numero_processo": "40014144520268260101", "meio": "D", "link": "https://eproc1g.tjsp.jus.br/eproc/externo_controlador.php?acao=consulta_publica_documento&numProcesso=40014144520268260101&idDocumento=611792430979779340300374443081&hash=e39b34c6e8242e6f3bc3bea64129d09d6f77f250e662ea21f3622427934dd812", "tipoDocumento": "Sentença", "nomeClasse": "PROCEDIMENTO DO JUIZADO ESPECIAL CíVEL", "codigoClasse": "436", "numeroComunicacao": 207, "ativo": true, "hash": "DLz5neGXZ4LsO9cGT73ww2Zdy4gaOk", "status": "P", "motivo_cancelamento": null, "data_cancelamento": null, "datadisponibilizacao": "21/10/2026", "meiocompleto": "Diário de Justiça Eletrônico Nacional", "numeroprocessocommascara": "4001414-45.2026.8.26.0101", "destinatarios": [{"comunicacao_id": 762302531, "nome": "[NOME]", "polo": "A"}], "destinatarioadvogados": [{"id": 1435807146, "comunicacao_id": 762302531, "advogado_id": 4666356, "created_at": "2026-10-20T00:02:07", "updated_at": "2026-10-20T00:02:07", "advogado": {"id": 4666356, "nome": "[NOME]", "numero_oab": "[OAB]", "uf_oab": "SP"}}]}, {"id": 762553590, "data_disponibilizacao": "2026-10-21", "siglaTribunal": "TJSP", "tipoComunicacao": "Edital", "nomeOrgao": "6ª Vara Criminal - [NOME] Criminal [NOME]", "idOrgao": 99331, "texto": "<style>
